//! `protoc-gen-ws-rs`: a `protoc` plugin emitting ws-proto service bindings
//! for Rust on top of message types generated by `protoc-gen-prost`.
//!
//! Built on the [`protoc_gen_prost`] library the same way `protoc-gen-tonic`
//! is: one output file per protobuf package, `<package>.ws.rs`, plus an
//! `include!` appended to the package's prost file via the `module`
//! insertion point (so run it with the same `out` as `protoc-gen-prost`).
//!
//! Per service it emits method descriptors, a `<Service>Handler` trait with
//! `register_<service>`, typed server/client stream wrappers and a
//! `<Service>Client` — the Rust counterpart of `protoc-gen-go-ws` output.

use std::str;

use prost::Message;
use prost_types::compiler::CodeGeneratorRequest;
use protoc_gen_prost::{Generator, InvalidParameter, ModuleRequestSet, Param, Params};

use self::{generator::WsGenerator, resolver::Resolver};

mod generator;
mod resolver;
mod util;

/// Execute the generator from a raw [`CodeGeneratorRequest`].
pub fn execute(raw_request: &[u8]) -> protoc_gen_prost::Result {
    let request = CodeGeneratorRequest::decode(raw_request)?;
    let params = request.parameter().parse::<Parameters>()?;

    let module_request_set = ModuleRequestSet::new(
        request.file_to_generate,
        request.proto_file,
        raw_request,
        params.default_package_filename.as_deref(),
        params.flat_output_dir,
    )?;

    let mut generator = WsGenerator {
        resolver: Resolver::new(params.extern_path, params.compile_well_known_types),
        generate_server: !params.no_server,
        generate_client: !params.no_client,
        insert_include: !params.no_include,
    };

    generator.generate(&module_request_set)
}

/// Plugin options. Same spelling as `protoc-gen-tonic` where they overlap.
///
/// * `default_package_filename=<value>`, `flat_output_dir`,
///   `extern_path=<proto>=<rust>`, `compile_well_known_types` — mirror the
///   `protoc-gen-prost` step so type paths resolve the same way.
/// * `no_server` / `no_client` — skip one side.
/// * `no_include` — do not append `include!("<pkg>.ws.rs")` to the prost file.
#[derive(Debug, Default)]
struct Parameters {
    default_package_filename: Option<String>,
    extern_path: Vec<(String, String)>,
    compile_well_known_types: bool,
    no_server: bool,
    no_client: bool,
    no_include: bool,
    flat_output_dir: bool,
}

impl str::FromStr for Parameters {
    type Err = InvalidParameter;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut p = Self::default();
        for param in Params::from_protoc_plugin_opts(s)? {
            match param {
                Param::Parameter {
                    param: "default_package_filename",
                }
                | Param::Value {
                    param: "default_package_filename",
                    ..
                } => p.default_package_filename = param.value().map(|s| s.to_string()),
                Param::KeyValue {
                    param: "extern_path",
                    key,
                    value,
                } => p.extern_path.push((key.to_string(), value)),
                Param::Parameter { param: flag }
                | Param::Value {
                    param: flag,
                    value: "true",
                } => match flag {
                    "compile_well_known_types" => p.compile_well_known_types = true,
                    "no_server" => p.no_server = true,
                    "no_client" => p.no_client = true,
                    "no_include" => p.no_include = true,
                    "flat_output_dir" => p.flat_output_dir = true,
                    _ => return Err(InvalidParameter::from(param)),
                },
                Param::Value {
                    param:
                        "compile_well_known_types"
                        | "no_server"
                        | "no_client"
                        | "no_include"
                        | "flat_output_dir",
                    value: "false",
                } => (),
                _ => return Err(InvalidParameter::from(param)),
            }
        }
        Ok(p)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use prost_types::{
        compiler::CodeGeneratorRequest, DescriptorProto, FileDescriptorProto,
        MethodDescriptorProto, ServiceDescriptorProto,
    };

    fn echo_request() -> Vec<u8> {
        let msg = |name: &str| DescriptorProto {
            name: Some(name.to_owned()),
            ..Default::default()
        };
        let method = |name: &str, cs: bool, ss: bool| MethodDescriptorProto {
            name: Some(name.to_owned()),
            input_type: Some(format!(".echo.v1.{name}Request")),
            output_type: Some(format!(".echo.v1.{name}Response")),
            client_streaming: Some(cs),
            server_streaming: Some(ss),
            ..Default::default()
        };
        CodeGeneratorRequest {
            file_to_generate: vec!["echo/v1/echo.proto".to_owned()],
            parameter: Some(String::new()),
            proto_file: vec![FileDescriptorProto {
                name: Some("echo/v1/echo.proto".to_owned()),
                package: Some("echo.v1".to_owned()),
                message_type: [
                    "UnaryRequest",
                    "UnaryResponse",
                    "ServerStreamRequest",
                    "ServerStreamResponse",
                ]
                .into_iter()
                .map(msg)
                .collect(),
                service: vec![ServiceDescriptorProto {
                    name: Some("EchoService".to_owned()),
                    method: vec![
                        method("Unary", false, false),
                        method("ServerStream", false, true),
                    ],
                    ..Default::default()
                }],
                ..Default::default()
            }],
            ..Default::default()
        }
        .encode_to_vec()
    }

    #[test]
    fn emits_ws_file_and_include() {
        let files = execute(&echo_request()).expect("codegen");
        let names: Vec<_> = files.iter().map(|f| f.name.as_deref().unwrap()).collect();
        assert_eq!(names, ["echo/v1/echo.v1.rs", "echo/v1/echo.v1.ws.rs"]);

        let include = &files[0];
        assert_eq!(include.insertion_point.as_deref(), Some("module"));
        assert_eq!(
            include.content.as_deref(),
            Some("include!(\"echo.v1.ws.rs\");\n")
        );

        let ws = files[1].content.as_deref().unwrap();
        assert!(ws.contains("pub mod echo_service_ws"), "{ws}");
        assert!(ws.contains("\"/echo.v1.EchoService/Unary\""), "{ws}");
        assert!(ws.contains("pub trait EchoServiceHandler"), "{ws}");
        assert!(ws.contains("Request<super::UnaryRequest>"), "{ws}");
        assert!(ws.contains("pub struct ServerStreamServerStream"), "{ws}");
        assert!(ws.contains("pub struct ServerStreamClientStream"), "{ws}");
        assert!(ws.contains("pub fn register_echo_service<"), "{ws}");
        assert!(ws.contains("pub struct EchoServiceClient"), "{ws}");
        assert!(ws.contains("StreamKind::ServerStream"), "{ws}");
    }

    #[test]
    fn rejects_unknown_parameter() {
        let err = "bogus".parse::<Parameters>().unwrap_err();
        assert!(err.to_string().contains("bogus"));
    }
}
